// Live ERP inputs for accreditation metrics, one academic year at a time. Each source returns the records behind its
// figure (the drill-down a reviewer or DVV partner asks for) and the figure computed from exactly those records, so the
// number on screen and the list under it never disagree.
import { sql, type SQL } from 'drizzle-orm';
import type { Tx } from '../db/db.service.js';

/** An academic year from 1 June to 31 May, for example 2025-26. `cal` is its first calendar year (publications are dated by calendar year). */
export interface AcademicYear {
  label: string;
  from: string;
  to: string;
  cal: number;
  /** True for the year that contains today: records without a date count only here. */
  current: boolean;
}

export const yearOf = (label: string, current = false): AcademicYear => {
  const y = Number(label.slice(0, 4));
  return { label: `${y}-${String((y + 1) % 100).padStart(2, '0')}`, from: `${y}-06-01`, to: `${y + 1}-05-31`, cal: y, current };
};

/** The window of `n` academic years ending with `cycle`, oldest first. */
export const windowOf = (cycle: string, n: number, currentLabel: string): AcademicYear[] => {
  const end = Number(cycle.slice(0, 4));
  return Array.from({ length: n }, (_, i) => {
    const y = yearOf(String(end - n + 1 + i));
    return { ...y, current: y.label === currentLabel };
  });
};

export type Cell = string | number | null;
export interface SourceResult {
  value: number | null;
  columns: string[];
  rows: Cell[][];
}

interface SourceDef {
  label: string;
  /** What the figure counts, for the formula panel. */
  basis: string;
  columns: string[];
  query: (y: AcademicYear) => SQL;
  /** How the figure comes from the rows: their count (default), the sum or the mean of a column, or a distinct count. */
  value?: { op: 'count' } | { op: 'sum' | 'avg' | 'median'; col: number; scale?: number } | { op: 'distinct'; col: number };
}

/** Teachers in service at some point in the year: active staff holding a teacher or head of department role. */
const TEACHERS = (y: AcademicYear) => sql`
  select distinct on (sp.user_id) sp.user_id, u.full_name, coalesce(d.name, '') as department, coalesce(dg.name, '') as designation, sp.employment_type,
         sp.date_of_joining, sp.date_of_leaving, coalesce(nullif(sp.gender, ''), '') as gender, sp.pan
  from staff_profiles sp join users u on u.id = sp.user_id join user_roles ur on ur.user_id = sp.user_id and ur.role in ('teacher', 'hod')
  left join departments d on d.id = sp.department_id left join designations dg on dg.id = sp.designation_id
  where coalesce(sp.date_of_joining, ${y.to}::date) <= ${y.to}::date
    and (sp.date_of_leaving is null or sp.date_of_leaving >= ${y.from}::date)
    and (sp.status = 'active' or sp.date_of_leaving is not null)`;
const FULLTIME = sql`t.employment_type <> 'visiting'`;
const DOCTORATE = sql`(q.kind = 'degree' and (q.level ilike '%doctor%' or q.title ~* '(ph\\.? ?d|doctor|d\\.?m\\.?$|m\\.? ?ch|d\\.?n\\.?b)'))`;
const NETSET = sql`(q.title ~* '(^|[^a-z])(net|set|slet|jrf)([^a-z]|$)')`;

/** Students on roll in the year; students without an enrolment date count only in the current year. */
const ON_ROLL = (y: AcademicYear) => sql`
  select s.id, s.roll_no, s.full_name, coalesce(pr.name, '') as program, coalesce(nullif(a.gender, ''), '') as gender, coalesce(nullif(a.category, ''), '') as category, s.status, s.enrolled_on, coalesce(sec.display_name, sec.name, '') as section
  from students s left join sections sec on sec.id = s.section_id left join programs pr on pr.id = sec.program_id left join applications a on a.id = s.application_id
  where ((s.enrolled_on is null and ${y.current}) or s.enrolled_on <= ${y.to}::date)
    and (s.status in ('enrolled', 'active') or coalesce(s.status_changed_at::date, ${y.to}::date) >= ${y.from}::date)`;

/** Sessions published in the year whose term is the programme's last: the outgoing (final-year) students. */
const FINAL_RESULTS = (y: AcademicYear) => sql`
  select distinct on (r.student_id) st.roll_no, st.full_name, pr.name as program, es.name as session, r.outcome, r.cgpa, coalesce(nullif(a.gender, ''), '') as gender
  from exam_results r join exam_sessions es on es.id = r.session_id join programs pr on pr.id = es.program_id join students st on st.id = r.student_id left join applications a on a.id = st.application_id
  where es.status in ('published', 'locked') and es.term = pr.term_count and es.published_at::date between ${y.from}::date and ${y.to}::date
  order by r.student_id, es.published_at desc`;

const GOVT_AGENCY = `(ugc|dst|serb|dbt|csir|icssr|icmr|icar|aicte|drdo|isro|barc|meity|mhrd|moe|ministry|government|govt|department of|state council|kscst|nbhm|dae|ichr)`;

export const SOURCES: Record<string, SourceDef> = {
  // ---- students and admissions -------------------------------------------------------------------------------------
  students_on_roll: { label: 'Students on roll', basis: 'Students enrolled or active at some point in the year', columns: ['Roll no.', 'Student', 'Programme', 'Gender', 'Category', 'Status', 'Enrolled on', 'Class / section'], query: (y) => sql`select roll_no, full_name, program, gender, category, status, enrolled_on::text, section from (${ON_ROLL(y)}) x order by program, roll_no` },
  students_women: { label: 'Women students on roll', basis: 'Students on roll whose application records the gender as female', columns: ['Roll no.', 'Student', 'Programme'], query: (y) => sql`select roll_no, full_name, program from (${ON_ROLL(y)}) x where lower(gender) in ('f', 'female') order by program, roll_no` },
  students_reserved: { label: 'Students from reserved categories', basis: 'Students on roll admitted under SC, ST, OBC, EWS or another reserved category', columns: ['Roll no.', 'Student', 'Programme', 'Category'], query: (y) => sql`select roll_no, full_name, program, category from (${ON_ROLL(y)}) x where category <> '' and lower(category) not in ('general', 'gen', 'open', 'gm', 'unreserved', 'ur') order by program, roll_no` },
  students_admitted: { label: 'Students admitted', basis: 'Students whose enrolment date falls in the year', columns: ['Roll no.', 'Student', 'Programme', 'Category', 'Enrolled on'], query: (y) => sql`select s.roll_no, s.full_name, coalesce(pr.name, ''), coalesce(a.category, ''), s.enrolled_on::text from students s left join sections sec on sec.id = s.section_id left join programs pr on pr.id = sec.program_id left join applications a on a.id = s.application_id where s.enrolled_on between ${y.from}::date and ${y.to}::date order by 3, 1` },
  seats_sanctioned: { label: 'Sanctioned seats', basis: 'Seats of the admission cycles that opened in the year', columns: ['Admission cycle', 'Programme', 'Seats'], value: { op: 'sum', col: 2 }, query: (y) => sql`select c.name, coalesce(pr.name, ''), c.seats from admission_cycles c left join programs pr on pr.id = c.program_id where coalesce(c.opens_on, c.created_at::date) between ${y.from}::date and ${y.to}::date order by 2, 1` },
  seats_reserved: { label: 'Seats reserved by category', basis: 'Reserved seats of the admission cycles that opened in the year', columns: ['Admission cycle', 'Category', 'Seats reserved'], value: { op: 'sum', col: 2 }, query: (y) => sql`select c.name, q.category, q.reserved_seats from admission_quotas q join admission_cycles c on c.id = q.cycle_id where coalesce(c.opens_on, c.created_at::date) between ${y.from}::date and ${y.to}::date order by 1, 2` },
  reserved_filled: { label: 'Reserved seats filled', basis: 'Applicants of a reserved category enrolled in a cycle that opened in the year', columns: ['Application', 'Applicant', 'Category', 'Admission cycle'], query: (y) => sql`select a.application_no, a.applicant_name, a.category, c.name from applications a join admission_cycles c on c.id = a.cycle_id where a.status = 'enrolled' and coalesce(c.opens_on, c.created_at::date) between ${y.from}::date and ${y.to}::date and coalesce(a.category, '') <> '' and lower(a.category) not in ('general', 'gen', 'open', 'gm', 'unreserved', 'ur') order by 4, 1` },
  programmes: { label: 'Programmes offered', basis: 'Programmes in the ERP', columns: ['Programme', 'Level', 'Code', 'Semesters'], query: () => sql`select name, level::text, coalesce(curriculum_code, ''), term_count from programs order by name` },
  courses: { label: 'Courses (subjects) offered', basis: 'Subjects defined across all programmes', columns: ['Programme', 'Semester', 'Code', 'Course'], query: () => sql`select pr.name, sj.term, sj.code, sj.name from subjects sj join programs pr on pr.id = sj.program_id order by 1, 2, 3` },

  // ---- examinations and outcomes -------------------------------------------------------------------------------------
  final_appeared: { label: 'Final-year students who appeared', basis: 'Students in a published final-semester session in the year', columns: ['Roll no.', 'Student', 'Programme', 'Session', 'Result', 'CGPA', 'Gender'], query: (y) => sql`select roll_no, full_name, program, session, outcome, cgpa, gender from (${FINAL_RESULTS(y)}) x order by program, roll_no` },
  final_passed: { label: 'Final-year students who passed', basis: 'Of those, the ones whose result is a pass', columns: ['Roll no.', 'Student', 'Programme', 'Session', 'CGPA'], query: (y) => sql`select roll_no, full_name, program, session, cgpa from (${FINAL_RESULTS(y)}) x where outcome = 'pass' order by program, roll_no` },
  result_days: { label: 'Days to declare results', basis: 'Mean days from the last day of each session to its publication', columns: ['Programme', 'Session', 'Last exam day', 'Result declared', 'Days'], value: { op: 'avg', col: 4 }, query: (y) => sql`select pr.name, es.name, es.ends_on::text, es.published_at::date::text, (es.published_at::date - es.ends_on) from exam_sessions es join programs pr on pr.id = es.program_id where es.ends_on is not null and es.published_at::date between ${y.from}::date and ${y.to}::date order by 4` },
  exam_candidates: { label: 'Students appearing in examinations', basis: 'Distinct students with a result in a session published in the year', columns: ['Roll no.', 'Student'], query: (y) => sql`select distinct st.roll_no, st.full_name from exam_results r join exam_sessions es on es.id = r.session_id join students st on st.id = r.student_id where es.published_at::date between ${y.from}::date and ${y.to}::date order by 1` },
  exam_grievances: { label: 'Examination grievances', basis: 'Revaluation, recounting and photocopy requests raised in the year', columns: ['Roll no.', 'Student', 'Course', 'Kind', 'Status', 'Raised on'], query: (y) => sql`select st.roll_no, st.full_name, coalesce(sj.name, ''), coalesce(r.kind, ''), r.status::text, r.created_at::date::text from revaluation_requests r join students st on st.id = r.student_id left join subjects sj on sj.id = r.subject_id where r.created_at::date between ${y.from}::date and ${y.to}::date order by 6` },
  cgpa_mean: { label: 'Mean CGPA of final-year students', basis: 'Mean CGPA in the latest final-semester result of each student in the year', columns: ['Roll no.', 'Student', 'Programme', 'CGPA'], value: { op: 'avg', col: 3 }, query: (y) => sql`select roll_no, full_name, program, cgpa from (${FINAL_RESULTS(y)}) x where cgpa is not null order by program, roll_no` },

  // ---- outcome-based education (latest attainment run; not dated) ------------------------------------------------------
  obe_cos: { label: 'Course outcomes defined', basis: 'Course outcomes in the OBE module', columns: ['Programme', 'Course', 'CO'], query: () => sql`select pr.name, sj.name, co.code from course_outcomes co join co_sets cs on cs.id = co.co_set_id join subjects sj on sj.id = cs.subject_id join programs pr on pr.id = sj.program_id order by 1, 2, 3` },
  obe_cos_mapped: { label: 'Course outcomes mapped to a PO or PSO', basis: 'Course outcomes with at least one entry in the CO-PO matrix', columns: ['Programme', 'Course', 'CO'], query: () => sql`select pr.name, sj.name, co.code from course_outcomes co join co_sets cs on cs.id = co.co_set_id join subjects sj on sj.id = cs.subject_id join programs pr on pr.id = sj.program_id where exists (select 1 from co_outcome_map m where m.co_id = co.id) order by 1, 2, 3` },
  obe_co_assessed: { label: 'Course outcomes assessed', basis: 'Course outcomes in the latest attainment run of each programme', columns: ['Programme', 'CO', 'Attainment', 'Target', 'Met'], query: () => sql`select p.name, x.code, x.combined, x.target, case when x.met then 'Yes' else 'No' end from (select distinct on (program_id, target_id) * from attainment_snapshots where scope = 'co' order by program_id, target_id, computed_at desc) x join programs p on p.id = x.program_id order by 1, 2` },
  obe_co_met: { label: 'Course outcomes that met the target', basis: 'Of those, the ones whose attainment met the target', columns: ['Programme', 'CO', 'Attainment', 'Target'], query: () => sql`select p.name, x.code, x.combined, x.target from (select distinct on (program_id, target_id) * from attainment_snapshots where scope = 'co' order by program_id, target_id, computed_at desc) x join programs p on p.id = x.program_id where x.met order by 1, 2` },
  obe_po_assessed: { label: 'POs and PSOs assessed', basis: 'Programme outcomes in the latest attainment run of each programme', columns: ['Programme', 'PO / PSO', 'Attainment', 'Target', 'Met'], query: () => sql`select p.name, x.code, x.combined, x.target, case when x.met then 'Yes' else 'No' end from (select distinct on (program_id, target_id) * from attainment_snapshots where scope = 'po' order by program_id, target_id, computed_at desc) x join programs p on p.id = x.program_id order by 1, 2` },
  obe_po_met: { label: 'POs and PSOs that met the target', basis: 'Of those, the ones whose attainment met the target', columns: ['Programme', 'PO / PSO', 'Attainment', 'Target'], query: () => sql`select p.name, x.code, x.combined, x.target from (select distinct on (program_id, target_id) * from attainment_snapshots where scope = 'po' order by program_id, target_id, computed_at desc) x join programs p on p.id = x.program_id where x.met order by 1, 2` },

  // ---- teachers ----------------------------------------------------------------------------------------------------
  teachers_fulltime: { label: 'Full-time teachers', basis: 'Teachers and heads of department in service in the year, other than visiting faculty', columns: ['Teacher', 'PAN', 'Department', 'Designation', 'Nature of appointment', 'Date of joining', 'Date of leaving'], query: (y) => sql`select full_name, coalesce(pan, ''), department, designation, employment_type, date_of_joining::text, date_of_leaving::text from (${TEACHERS(y)}) t where ${FULLTIME} order by department, full_name` },
  teachers_all: { label: 'Teachers including visiting faculty', basis: 'Teachers and heads of department in service in the year', columns: ['Teacher', 'Department', 'Designation', 'Nature of appointment', 'Gender', 'Date of joining'], query: (y) => sql`select full_name, department, designation, employment_type, gender, date_of_joining::text from (${TEACHERS(y)}) t order by department, full_name` },
  teachers_women: { label: 'Women full-time teachers', basis: 'Full-time teachers whose staff record gives the gender as female', columns: ['Teacher', 'Department'], query: (y) => sql`select full_name, department from (${TEACHERS(y)}) t where ${FULLTIME} and lower(t.gender) in ('f', 'female') order by 2, 1` },
  teachers_doctorate: { label: 'Full-time teachers with a doctorate', basis: 'Full-time teachers with a Ph.D., D.M., M.Ch. or D.N.B. recorded and awarded by the end of the year', columns: ['Teacher', 'Department', 'Qualification', 'Year of award', 'Awarding body'], query: (y) => sql`select distinct on (t.user_id) t.full_name, t.department, q.title, q.year, q.institution from (${TEACHERS(y)}) t join staff_qualifications q on q.user_id = t.user_id where ${FULLTIME} and ${DOCTORATE} and coalesce(q.year, ${y.cal + 1}) <= ${y.cal + 1} order by t.user_id, q.year` },
  teachers_doctorate_netset: { label: 'Full-time teachers with a doctorate or NET/SET/SLET', basis: 'Full-time teachers holding a doctorate or a NET, SET or SLET qualification', columns: ['Teacher', 'Department', 'Qualification', 'Year'], query: (y) => sql`select distinct on (t.user_id) t.full_name, t.department, q.title, q.year from (${TEACHERS(y)}) t join staff_qualifications q on q.user_id = t.user_id where ${FULLTIME} and (${DOCTORATE} or ${NETSET}) and coalesce(q.year, ${y.cal + 1}) <= ${y.cal + 1} order by t.user_id, q.year` },
  teachers_pg: { label: 'Full-time teachers with a postgraduate degree (M.E./M.Tech. or equivalent)', basis: 'Full-time teachers without a doctorate whose degrees include a master\'s', columns: ['Teacher', 'Department', 'Qualification'], query: (y) => sql`select distinct on (t.user_id) t.full_name, t.department, q.title from (${TEACHERS(y)}) t join staff_qualifications q on q.user_id = t.user_id where ${FULLTIME} and q.kind = 'degree' and (q.level ilike '%post%' or q.level ilike '%master%' or q.title ~* '(m\\.? ?tech|m\\.? ?e\\.?$|m\\.?sc|m\\.?a\\.?$|m\\.?com|mba|m\\.? ?phil|master)') and not exists (select 1 from staff_qualifications q2 where q2.user_id = t.user_id and (q2.kind = 'degree' and (q2.level ilike '%doctor%' or q2.title ~* '(ph\\.? ?d|doctor)'))) order by t.user_id` },
  teacher_experience: { label: 'Teaching experience of full-time teachers (years)', basis: 'Years from joining to the end of the year, per full-time teacher', columns: ['Teacher', 'Department', 'Date of joining', 'Years'], value: { op: 'sum', col: 3 }, query: (y) => sql`select full_name, department, date_of_joining::text, round((least(coalesce(date_of_leaving, ${y.to}::date), ${y.to}::date) - date_of_joining) / 365.25, 2)::float8 from (${TEACHERS(y)}) t where ${FULLTIME} and date_of_joining is not null order by 4 desc` },
  teachers_exp_lt8: { label: 'Faculty with up to 8 years of experience', basis: 'Full-time teachers whose service at the end of the year is 8 years or less', columns: ['Teacher', 'Years'], query: (y) => sql`select full_name, round((${y.to}::date - date_of_joining) / 365.25, 1)::float8 from (${TEACHERS(y)}) t where ${FULLTIME} and date_of_joining is not null and (${y.to}::date - date_of_joining) / 365.25 <= 8 order by 1` },
  teachers_exp_8_15: { label: 'Faculty with 8 to 15 years of experience', basis: 'Full-time teachers with more than 8 and up to 15 years of service', columns: ['Teacher', 'Years'], query: (y) => sql`select full_name, round((${y.to}::date - date_of_joining) / 365.25, 1)::float8 from (${TEACHERS(y)}) t where ${FULLTIME} and date_of_joining is not null and (${y.to}::date - date_of_joining) / 365.25 > 8 and (${y.to}::date - date_of_joining) / 365.25 <= 15 order by 1` },
  teachers_exp_gt15: { label: 'Faculty with more than 15 years of experience', basis: 'Full-time teachers with more than 15 years of service', columns: ['Teacher', 'Years'], query: (y) => sql`select full_name, round((${y.to}::date - date_of_joining) / 365.25, 1)::float8 from (${TEACHERS(y)}) t where ${FULLTIME} and date_of_joining is not null and (${y.to}::date - date_of_joining) / 365.25 > 15 order by 1` },
  teachers_professor: { label: 'Professors', basis: 'Full-time teachers whose designation is Professor (not Assistant or Associate)', columns: ['Teacher', 'Department', 'Designation'], query: (y) => sql`select full_name, department, designation from (${TEACHERS(y)}) t where ${FULLTIME} and designation ilike '%professor%' and designation not ilike '%assist%' and designation not ilike '%assoc%' order by 2, 1` },
  teachers_associate: { label: 'Associate professors', basis: 'Full-time teachers whose designation is Associate Professor', columns: ['Teacher', 'Department', 'Designation'], query: (y) => sql`select full_name, department, designation from (${TEACHERS(y)}) t where ${FULLTIME} and designation ilike '%assoc%' order by 2, 1` },
  teachers_assistant: { label: 'Assistant professors', basis: 'Full-time teachers whose designation is Assistant Professor or Lecturer', columns: ['Teacher', 'Department', 'Designation'], query: (y) => sql`select full_name, department, designation from (${TEACHERS(y)}) t where ${FULLTIME} and (designation ilike '%assist%' or designation ilike '%lecturer%') order by 2, 1` },
  teachers_left: { label: 'Teachers who left', basis: 'Full-time teachers whose date of leaving falls in the year', columns: ['Teacher', 'Department', 'Date of leaving'], query: (y) => sql`select full_name, department, date_of_leaving::text from (${TEACHERS(y)}) t where ${FULLTIME} and date_of_leaving between ${y.from}::date and ${y.to}::date order by 3` },
  teachers_fdp: { label: 'Teachers who attended professional development programmes', basis: 'Distinct teachers with an FDP, workshop, conference or course recorded in the year', columns: ['Teacher', 'Programme', 'Kind', 'Organiser', 'From', 'To'], value: { op: 'distinct', col: 0 }, query: (y) => sql`select u.full_name, tr.title, tr.kind, tr.organiser, tr.starts_on::text, tr.ends_on::text from training_records tr join users u on u.id = tr.user_id where tr.starts_on between ${y.from}::date and ${y.to}::date order by 1, 5` },
  fdp_programmes: { label: 'Professional development programmes attended', basis: 'Training records plus FDP evidence uploaded by teachers in the year', columns: ['Teacher', 'Programme', 'Kind', 'Date or year'], query: (y) => sql`select u.full_name, tr.title, tr.kind, tr.starts_on::text from training_records tr join users u on u.id = tr.user_id where tr.starts_on between ${y.from}::date and ${y.to}::date
      union all select u.full_name, fe.title, 'fdp', fe.year::text from faculty_evidence fe join users u on u.id = fe.user_id where fe.kind = 'fdp' and fe.year = ${y.cal} order by 1` },
  teacher_awards: { label: 'Awards and recognition received by teachers', basis: 'Awards and fellowships in the research office register, plus award evidence uploaded by teachers, for the year', columns: ['Teacher', 'Award', 'Awarding body', 'Year', 'Level'], value: { op: 'distinct', col: 0 }, query: (y) => sql`select u.full_name, r.title, r.body, extract(year from r.received_on)::int, r.level from research_recognitions r join users u on u.id = r.user_id where r.kind in ('award', 'fellowship') and r.received_on between ${y.from}::date and ${y.to}::date
      union all select u.full_name, fe.title, fe.venue, fe.year, '' from faculty_evidence fe join users u on u.id = fe.user_id where fe.kind = 'award' and fe.year = ${y.cal} order by 1` },
  teacher_fellowships: { label: 'Teachers receiving fellowships', basis: 'Fellowships in the research office register received in the year', columns: ['Name of the teacher awarded national / international fellowship / financial support', 'Name of the award / fellowship', 'Year of award', 'Awarding agency'], value: { op: 'distinct', col: 0 }, query: (y) => sql`select u.full_name, r.title, extract(year from r.received_on)::int, r.body from research_recognitions r join users u on u.id = r.user_id where r.kind = 'fellowship' and r.received_on between ${y.from}::date and ${y.to}::date order by 1` },
  research_awards: { label: 'Research awards and recognitions', basis: 'Awards in the research office register received in the year', columns: ['Name of the awardee', 'Name of the award', 'Awarding agency', 'Year of award'], query: (y) => sql`select u.full_name, r.title, r.body, extract(year from r.received_on)::int from research_recognitions r join users u on u.id = r.user_id where r.kind = 'award' and r.received_on between ${y.from}::date and ${y.to}::date order by 1` },
  staff_nonteaching: { label: 'Non-teaching staff', basis: 'Active staff without a teacher or head of department role', columns: ['Name', 'Department', 'Designation', 'Gender', 'Nature of appointment'], query: (y) => sql`select u.full_name, coalesce(d.name, ''), coalesce(dg.name, ''), coalesce(sp.gender, ''), sp.employment_type from staff_profiles sp join users u on u.id = sp.user_id left join departments d on d.id = sp.department_id left join designations dg on dg.id = sp.designation_id where coalesce(sp.date_of_joining, ${y.to}::date) <= ${y.to}::date and (sp.date_of_leaving is null or sp.date_of_leaving >= ${y.from}::date) and not exists (select 1 from user_roles ur where ur.user_id = sp.user_id and ur.role in ('teacher', 'hod')) order by 2, 1` },
  teachers_trained: { label: 'Teachers with in-service training', basis: 'Distinct teachers with a training record in the year', columns: ['Teacher', 'Programmes'], query: (y) => sql`select u.full_name, count(*)::int from training_records tr join users u on u.id = tr.user_id where tr.starts_on between ${y.from}::date and ${y.to}::date group by u.full_name order by 1` },
  mentees: { label: 'Students with a mentor', basis: 'Mentor assignments active in the year', columns: ['Student', 'Mentor', 'From'], query: (y) => sql`select st.full_name, u.full_name, ma.started_on::text from mentor_assignments ma join students st on st.id = ma.student_id join users u on u.id = ma.mentor_user_id where coalesce(ma.started_on, ${y.from}::date) <= ${y.to}::date and (ma.ended_on is null or ma.ended_on >= ${y.from}::date) order by 2, 1` },
  mentors: { label: 'Mentors', basis: 'Distinct mentors with an assignment active in the year', columns: ['Mentor', 'Students'], value: { op: 'count' }, query: (y) => sql`select u.full_name, count(*)::int from mentor_assignments ma join users u on u.id = ma.mentor_user_id where coalesce(ma.started_on, ${y.from}::date) <= ${y.to}::date and (ma.ended_on is null or ma.ended_on >= ${y.from}::date) group by u.full_name order by 1` },

  // ---- research -----------------------------------------------------------------------------------------------------
  grants_lakhs: { label: 'Research grants sanctioned (INR lakhs)', basis: 'Grants sanctioned to research projects, by the start date of the grant', columns: ['Project', 'Principal investigator', 'Funding agency', 'Scheme', 'Year of award', 'Amount (INR lakhs)'], value: { op: 'sum', col: 5 }, query: (y) => sql`select coalesce(rp.title, ''), coalesce(u.full_name, ''), g.agency, coalesce(g.scheme, ''), extract(year from g.starts_on)::int, round(g.sanctioned_paise / 1e7, 2)::float8 from research_grants g left join research_projects rp on rp.id = g.project_id left join users u on u.id = rp.pi_user_id where g.status <> 'cancelled' and g.starts_on between ${y.from}::date and ${y.to}::date order by 5, 1` },
  grants_govt_lakhs: { label: 'Grants from government agencies (INR lakhs)', basis: `Grants whose agency name matches a government body (${GOVT_AGENCY.slice(1, -1).replace(/\|/g, ', ')})`, columns: ['Project', 'Funding agency', 'Amount (INR lakhs)'], value: { op: 'sum', col: 2 }, query: (y) => sql`select coalesce(rp.title, ''), g.agency, round(g.sanctioned_paise / 1e7, 2)::float8 from research_grants g left join research_projects rp on rp.id = g.project_id where g.status <> 'cancelled' and g.starts_on between ${y.from}::date and ${y.to}::date and g.agency ~* ${GOVT_AGENCY} order by 1` },
  grants_nongovt_lakhs: { label: 'Grants from non-government agencies (INR lakhs)', basis: 'Grants whose agency is not a government body', columns: ['Project', 'Funding agency', 'Amount (INR lakhs)'], value: { op: 'sum', col: 2 }, query: (y) => sql`select coalesce(rp.title, ''), g.agency, round(g.sanctioned_paise / 1e7, 2)::float8 from research_grants g left join research_projects rp on rp.id = g.project_id where g.status <> 'cancelled' and g.starts_on between ${y.from}::date and ${y.to}::date and g.agency !~* ${GOVT_AGENCY} order by 1` },
  research_projects: { label: 'Sponsored research projects', basis: 'Research projects starting in the year, other than cancelled ones', columns: ['Project', 'Principal investigator', 'Sponsor', 'Start', 'Status'], query: (y) => sql`select rp.title, coalesce(u.full_name, ''), coalesce(rp.sponsor_org, ''), rp.starts_on::text, rp.status from research_projects rp left join users u on u.id = rp.pi_user_id where rp.status <> 'cancelled' and rp.starts_on between ${y.from}::date and ${y.to}::date order by 4` },
  research_guides: { label: 'Recognised research guides', basis: 'Distinct supervisors of research scholars enrolled by the end of the year', columns: ['Guide', 'Scholars'], query: (y) => sql`select u.full_name, count(*)::int from research_scholars rs join users u on u.id = rs.supervisor_user_id where coalesce(rs.enrolled_on, ${y.to}::date) <= ${y.to}::date group by u.full_name order by 1` },
  phd_registered: { label: 'Ph.D. scholars registered', basis: 'Research scholars enrolled in the year', columns: ['Scholar', 'Programme', 'Guide', 'Enrolled on'], query: (y) => sql`select rs.full_name, rs.programme, coalesce(u.full_name, ''), rs.enrolled_on::text from research_scholars rs left join users u on u.id = rs.supervisor_user_id where rs.enrolled_on between ${y.from}::date and ${y.to}::date order by 4` },
  phd_on_roll: { label: 'Ph.D. scholars on roll', basis: 'Research scholars enrolled by the end of the year and not yet awarded or withdrawn before it began', columns: ['Scholar', 'Programme', 'Status'], query: (y) => sql`select rs.full_name, rs.programme, rs.status from research_scholars rs where coalesce(rs.enrolled_on, ${y.to}::date) <= ${y.to}::date and (rs.completed_on is null or rs.completed_on >= ${y.from}::date) and rs.status <> 'withdrawn' order by 1` },
  phd_awarded: { label: 'Ph.D. degrees awarded', basis: 'Research scholars awarded in the year', columns: ['Scholar', 'Thesis', 'Guide', 'Awarded on'], query: (y) => sql`select rs.full_name, coalesce(rs.thesis_title, ''), coalesce(u.full_name, ''), rs.completed_on::text from research_scholars rs left join users u on u.id = rs.supervisor_user_id where rs.status = 'awarded' and rs.completed_on between ${y.from}::date and ${y.to}::date order by 4` },
  papers_journal: { label: 'Research papers in journals', basis: 'Journal publications of the calendar year in which the academic year starts, plus verified teacher-uploaded papers', columns: ['Title of paper', 'Name of the author(s)', 'Name of journal', 'Year of publication', 'ISSN number', 'Indexed in'], query: (y) => sql`select p.title, coalesce((select string_agg(coalesce(a->>'name', a #>> '{}'), ', ') from jsonb_array_elements(p.authors) a), ''), coalesce(p.venue, ''), p.year, coalesce(p.issn, ''), coalesce(array_to_string(p.indexed_in, ', '), '') from publications p where p.kind = 'journal' and p.year = ${y.cal} and p.status <> 'retracted'
      union all select fe.title, u.full_name, fe.venue, fe.year, '', '' from faculty_evidence fe join users u on u.id = fe.user_id where fe.kind = 'publication' and fe.verified and fe.year = ${y.cal} order by 1` },
  papers_indexed: { label: 'Papers indexed in Scopus or Web of Science', basis: 'Publications of the year with an indexing service recorded', columns: ['Title', 'Journal', 'Year', 'Indexed in', 'DOI'], query: (y) => sql`select p.title, coalesce(p.venue, ''), p.year, array_to_string(p.indexed_in, ', '), coalesce(p.doi, '') from publications p where p.year = ${y.cal} and p.status <> 'retracted' and coalesce(array_length(p.indexed_in, 1), 0) > 0 order by 1` },
  books_chapters: { label: 'Books, chapters and conference papers', basis: 'Books, book chapters and conference papers of the year, plus verified teacher-uploaded books', columns: ['Title of the book or chapter', 'Name of the teacher', 'Title of the proceedings or publisher', 'Year of publication', 'ISBN or ISSN'], query: (y) => sql`select p.title, coalesce((select string_agg(coalesce(a->>'name', a #>> '{}'), ', ') from jsonb_array_elements(p.authors) a), ''), coalesce(p.venue, ''), p.year, coalesce(p.issn, '') from publications p where p.kind in ('book', 'book_chapter', 'conference') and p.year = ${y.cal} and p.status <> 'retracted'
      union all select fe.title, u.full_name, fe.venue, fe.year, '' from faculty_evidence fe join users u on u.id = fe.user_id where fe.kind = 'book' and fe.verified and fe.year = ${y.cal} order by 1` },
  patents_filed: { label: 'Patents filed', basis: 'Patents and other IP filed in the year', columns: ['Title', 'Kind', 'Application no.', 'Filed on', 'Status'], query: (y) => sql`select title, kind, coalesce(application_no, ''), filed_on::text, status from patents where filed_on between ${y.from}::date and ${y.to}::date order by 4` },
  patents_published: { label: 'Patents published', basis: 'Patents filed in the year whose status is published or granted', columns: ['Title', 'Application no.', 'Filed on', 'Status'], query: (y) => sql`select title, coalesce(application_no, ''), filed_on::text, status from patents where status in ('published', 'granted') and filed_on between ${y.from}::date and ${y.to}::date order by 3` },
  patents_granted: { label: 'Patents granted', basis: 'Patents granted in the year', columns: ['Title', 'Application no.', 'Granted on'], query: (y) => sql`select title, coalesce(application_no, ''), granted_on::text from patents where status = 'granted' and granted_on between ${y.from}::date and ${y.to}::date order by 3` },
  seed_money_lakhs: { label: 'Seed money granted (INR lakhs)', basis: 'Seed grants sanctioned in the year', columns: ['Name of the teacher provided with seed money', 'Name of the department', 'Amount of seed money (INR lakhs)', 'Year of receiving'], value: { op: 'sum', col: 2 }, query: (y) => sql`select u.full_name, coalesce(d.name, ''), round(g.sanctioned_paise / 1e7, 2)::float8, extract(year from g.sanctioned_on)::int from research_seed_grants g join users u on u.id = g.applicant_user_id left join departments d on d.id = g.department_id where g.status in ('sanctioned', 'completed') and g.sanctioned_on between ${y.from}::date and ${y.to}::date order by 1` },
  consultancy_lakhs: { label: 'Revenue from consultancy and corporate training (INR lakhs)', basis: 'Consultancy, testing and corporate training starting in the year (amount received)', columns: ['Name of the teacher-consultant / trainer', 'Name of the consultancy project / corporate training programme', 'Consulting / sponsoring agency with contact details', 'Year', 'Revenue generated (INR lakhs)', 'Number of trainees'], value: { op: 'sum', col: 4 }, query: (y) => sql`select coalesce(u.full_name, ''), c.title, c.client || coalesce(', ' || c.client_contact, ''), extract(year from coalesce(c.starts_on, c.created_at::date))::int, round(c.received_paise / 1e7, 2)::float8, c.trainees from research_consultancies c left join users u on u.id = c.lead_user_id where c.status <> 'cancelled' and coalesce(c.starts_on, c.created_at::date) between ${y.from}::date and ${y.to}::date order by 2` },
  mous_functional: { label: 'Functional MoUs', basis: 'MoUs in force during the year with at least one activity recorded in it', columns: ['Name of the organisation / institution / industry with whom the MoU is signed', 'Year of signing MoU', 'Duration', 'List the actual activities under each MoU and web links year-wise'], query: (y) => sql`select m.partner, extract(year from m.signed_on)::int, coalesce(to_char(m.signed_on, 'DD-MM-YYYY') || ' to ' || to_char(m.valid_until, 'DD-MM-YYYY'), 'Open-ended'), string_agg(a.title || ' (' || to_char(a.held_on, 'DD-MM-YYYY') || ')', '; ' order by a.held_on) from research_mous m join research_mou_activities a on a.mou_id = m.id and a.held_on between ${y.from}::date and ${y.to}::date where m.signed_on <= ${y.to}::date and (m.valid_until is null or m.valid_until >= ${y.from}::date) group by m.id, m.partner, m.signed_on, m.valid_until order by 1` },
  ipr_workshops: { label: 'Workshops and seminars (research methodology, IPR, entrepreneurship)', basis: 'Seminars, workshops and conferences held in the year', columns: ['Name of the workshop or seminar', 'Type', 'Date', 'Venue'], query: (y) => sql`select title, event_type, starts_at::date::text, coalesce(venue, '') from campus_events where event_type in ('seminar', 'workshop', 'conference') and status <> 'cancelled' and starts_at::date between ${y.from}::date and ${y.to}::date order by 3` },

  // ---- student support and progression -------------------------------------------------------------------------------
  placed: { label: 'Students placed', basis: 'Distinct students with a standing placement offer made in the year', columns: ['Name of student placed', 'Programme', 'Name of the employer', 'Pay package (LPA)', 'Offered on'], value: { op: 'distinct', col: 0 }, query: (y) => sql`select st.full_name, coalesce(pr.name, ''), c.name, po.ctc_lpa::float8, po.offered_on::text from placement_offers po join placement_drives d on d.id = po.drive_id join placement_companies c on c.id = d.company_id join students st on st.id = po.student_id left join sections sec on sec.id = st.section_id left join programs pr on pr.id = sec.program_id where po.status in ('offered', 'accepted') and po.offered_on between ${y.from}::date and ${y.to}::date order by 1` },
  median_salary: { label: 'Median salary of placed graduates (INR lakhs a year)', basis: 'Median CTC over the best standing offer of each student placed in the year', columns: ['Student', 'Best offer (LPA)'], value: { op: 'median', col: 1 }, query: (y) => sql`select st.full_name, max(po.ctc_lpa)::float8 from placement_offers po join students st on st.id = po.student_id where po.status in ('offered', 'accepted') and po.ctc_lpa is not null and po.offered_on between ${y.from}::date and ${y.to}::date group by st.id, st.full_name order by 2` },
  internships: { label: 'Students doing internships or field projects', basis: 'Distinct students with an internship starting in the year', columns: ['Student', 'Organisation', 'Title', 'From', 'To'], value: { op: 'distinct', col: 0 }, query: (y) => sql`select st.full_name, coalesce(i.org_name, ''), i.title, i.starts_on::text, i.ends_on::text from internships i join students st on st.id = i.student_id where i.starts_on between ${y.from}::date and ${y.to}::date order by 1` },
  scholarship_students: { label: 'Students benefited by scholarships and freeships', basis: 'Approved scholarship applications and approved scholarship or freeship concessions decided in the year (distinct students)', columns: ['Name of the student', 'Scheme', 'Amount (INR)', 'Decided on'], value: { op: 'distinct', col: 0 }, query: (y) => sql`select st.full_name, sc.name, round(coalesce(sa.awarded_paise, 0) / 100.0)::float8, sa.decided_at::date::text from scholarship_applications sa join scholarship_schemes sc on sc.id = sa.scheme_id join students st on st.id = sa.student_id where sa.status = 'approved' and sa.decided_at::date between ${y.from}::date and ${y.to}::date
      union all select st.full_name, coalesce(nullif(fc.sponsor_name, ''), fc.kind), round(coalesce(fc.applied_paise, fc.amount_paise, 0) / 100.0)::float8, fc.decided_at::date::text from fee_concessions fc join students st on st.id = fc.student_id where fc.status = 'approved' and fc.kind in ('scholarship', 'sponsor', 'merit') and fc.decided_at::date between ${y.from}::date and ${y.to}::date order by 1` },
  full_fee_waiver: { label: 'Students with full tuition fee reimbursement', basis: 'Distinct students with an approved 100 per cent concession decided in the year', columns: ['Student', 'Kind', 'Sponsor'], value: { op: 'distinct', col: 0 }, query: (y) => sql`select st.full_name, fc.kind, coalesce(fc.sponsor_name, '') from fee_concessions fc join students st on st.id = fc.student_id where fc.status = 'approved' and fc.percent = 100 and fc.decided_at::date between ${y.from}::date and ${y.to}::date order by 1` },
  counselled: { label: 'Students given career or competitive examination guidance', basis: 'Distinct students with a counselling session in the year', columns: ['Student', 'Reason', 'Scheduled on'], value: { op: 'distinct', col: 0 }, query: (y) => sql`select st.full_name, coalesce(cs.reason, ''), cs.scheduled_at::date::text from counselling_sessions cs join students st on st.id = cs.student_id where coalesce(cs.scheduled_at, cs.created_at)::date between ${y.from}::date and ${y.to}::date order by 1` },
  grievances: { label: 'Student grievances', basis: 'Grievance tickets raised in the year', columns: ['Ticket', 'Category', 'Raised on', 'Status', 'Resolved on'], query: (y) => sql`select ticket_no, category, created_at::date::text, status, resolved_at::date::text from grievance_tickets where created_at::date between ${y.from}::date and ${y.to}::date order by 3` },
  grievances_resolved: { label: 'Student grievances resolved', basis: 'Grievance tickets raised in the year and resolved', columns: ['Ticket', 'Category', 'Resolved on'], query: (y) => sql`select ticket_no, category, resolved_at::date::text from grievance_tickets where resolved_at is not null and created_at::date between ${y.from}::date and ${y.to}::date order by 3` },
  student_awards: { label: 'Awards and medals won by students', basis: 'Club achievements at state, national or international level in the year', columns: ['Name of the award or medal', 'Level', 'Position', 'Date'], query: (y) => sql`select title, level, coalesce(position, ''), achieved_on::text from club_achievements where level in ('district', 'state', 'national', 'international') and achieved_on between ${y.from}::date and ${y.to}::date order by 4` },
  sports_cultural_events: { label: 'Sports and cultural events', basis: 'Fests, sports and competitions held in the year', columns: ['Name of the event', 'Type', 'Date'], query: (y) => sql`select title, event_type, starts_at::date::text from campus_events where event_type in ('fest', 'sports', 'competition') and status <> 'cancelled' and starts_at::date between ${y.from}::date and ${y.to}::date order by 3` },
  extension_activities: { label: 'Extension and outreach programmes', basis: 'Activities of service clubs (NSS, NCC and similar) in the year', columns: ['Name of the activity', 'Organising unit', 'Date'], query: (y) => sql`select a.title, c.name, a.activity_on::text from club_activities a join clubs c on c.id = a.club_id where c.category = 'service' and a.activity_on between ${y.from}::date and ${y.to}::date order by 3` },
  value_added_courses: { label: 'Value-added and add-on courses offered', basis: 'Course offerings in the value-added (VAC), skill or ability category in a term of the year', columns: ['Name of the course', 'Course code', 'Category', 'Students enrolled'], query: (y) => sql`select sj.name, sj.code, co.category, (select count(*)::int from course_registrations cr where cr.offering_id = co.id and cr.status = 'registered') from course_offerings co join subjects sj on sj.id = co.subject_id left join academic_terms t on t.id = co.term_id where co.category in ('vac', 'skill', 'ability') and coalesce(t.starts_on, co.created_at::date) between ${y.from}::date and ${y.to}::date order by 1` },
  value_added_students: { label: 'Students enrolled in value-added courses', basis: 'Distinct students registered for a value-added, skill or ability course in a term of the year', columns: ['Student', 'Course'], value: { op: 'distinct', col: 0 }, query: (y) => sql`select st.full_name, sj.name from course_registrations cr join course_offerings co on co.id = cr.offering_id join subjects sj on sj.id = co.subject_id join students st on st.id = cr.student_id left join academic_terms t on t.id = co.term_id where co.category in ('vac', 'skill', 'ability') and cr.status = 'registered' and coalesce(t.starts_on, co.created_at::date) between ${y.from}::date and ${y.to}::date order by 1` },
  alumni_contribution_lakhs: { label: 'Alumni contribution (INR lakhs)', basis: 'Donations received from alumni in the year', columns: ['Donor', 'Received on', 'Amount (INR lakhs)'], value: { op: 'sum', col: 2 }, query: (y) => sql`select donor_name, received_on::text, round(amount_paise / 1e7, 4)::float8 from alumni_donations where received_on between ${y.from}::date and ${y.to}::date order by 2` },

  // ---- infrastructure, library and finance ----------------------------------------------------------------------------
  classrooms: { label: 'Classrooms and seminar halls', basis: 'Rooms recorded as classrooms, lecture halls or seminar halls', columns: ['Room', 'Kind', 'Capacity'], query: () => sql`select name, coalesce(kind, ''), capacity from rooms where coalesce(kind, 'classroom') ~* '(class|lecture|seminar|hall|tutorial)' order by 1` },
  ict_rooms: { label: 'Classrooms with ICT facilities', basis: 'Rooms with a smart board or other ICT device enrolled', columns: ['Room', 'Device'], value: { op: 'distinct', col: 0 }, query: () => sql`select r.name, d.name from rooms r join devices d on d.room_id = r.id order by 1` },
  computers: { label: 'Computers available to students', basis: 'Assets in a computer, laptop or desktop category that are in use', columns: ['Tag', 'Asset', 'Location'], query: () => sql`select tag, name, coalesce(location, '') from assets where category ~* '(computer|laptop|desktop|workstation|pc)' and coalesce(status, 'active') not in ('disposed', 'lost', 'retired') order by 1` },
  capex_lakhs: { label: 'Expenditure on infrastructure augmentation (INR lakhs)', basis: 'Cost of assets bought in the year (capital expenditure, excluding salary)', columns: ['Tag', 'Asset', 'Category', 'Purchased on', 'Amount (INR lakhs)'], value: { op: 'sum', col: 4 }, query: (y) => sql`select tag, name, coalesce(category, ''), purchased_on::text, round(coalesce(cost_paise, 0) / 1e7, 4)::float8 from assets where purchased_on between ${y.from}::date and ${y.to}::date order by 4` },
  maintenance_lakhs: { label: 'Expenditure on maintenance (INR lakhs)', basis: 'Asset maintenance and AMC contracts starting in the year, excluding salary', columns: ['Item', 'Kind', 'Date', 'Amount (INR lakhs)'], value: { op: 'sum', col: 3 }, query: (y) => sql`select coalesce(a.name, ''), m.kind, m.done_on::text, round(coalesce(m.cost_paise, 0) / 1e7, 4)::float8 from asset_maintenance m left join assets a on a.id = m.asset_id where m.done_on between ${y.from}::date and ${y.to}::date
      union all select title, 'AMC', starts_on::text, round(coalesce(cost_paise, 0) / 1e7, 4)::float8 from amc_contracts where starts_on between ${y.from}::date and ${y.to}::date order by 3` },
  opex_lakhs: { label: 'Operational expenditure (INR lakhs)', basis: 'Salaries paid (employer cost of payroll months in the year) plus departmental expenses', columns: ['Head', 'Month or date', 'Amount (INR lakhs)'], value: { op: 'sum', col: 2 }, query: (y) => sql`select 'Salaries', r.month, round(sum(ps.employer_cost_paise) / 1e7, 4)::float8 from payroll_runs r join payslips ps on ps.run_id = r.id where to_date(r.month || '-01', 'YYYY-MM-DD') between ${y.from}::date and ${y.to}::date group by r.month
      union all select coalesce(description, 'Expense'), spent_on::text, round(amount_paise / 1e7, 4)::float8 from cost_expenses where spent_on between ${y.from}::date and ${y.to}::date order by 2` },
  library_spend_lakhs: { label: 'Expenditure on books and journals (INR lakhs)', basis: 'Price times copies of library books added in the year', columns: ['Title', 'Copies', 'Added on', 'Amount (INR lakhs)'], value: { op: 'sum', col: 3 }, query: (y) => sql`select title, copies, created_at::date::text, round(coalesce(price_paise, 0) * coalesce(copies, 1) / 1e7, 4)::float8 from library_books where created_at::date between ${y.from}::date and ${y.to}::date order by 3` },
  library_loans: { label: 'Library loans', basis: 'Books issued in the year', columns: ['Book', 'Borrower', 'Issued on'], query: (y) => sql`select b.title, coalesce(st.full_name, ''), l.issued_at::date::text from library_loans l join library_books b on b.id = l.book_id left join students st on st.id = l.student_id where l.issued_at::date between ${y.from}::date and ${y.to}::date order by 3` },
  library_days: { label: 'Days the library issued books', basis: 'Distinct days with at least one loan in the year', columns: ['Day', 'Loans'], query: (y) => sql`select issued_at::date::text, count(*)::int from library_loans where issued_at::date between ${y.from}::date and ${y.to}::date group by 1 order by 1` },
  library_titles: { label: 'Library books (copies)', basis: 'Copies of the books catalogued in the library', columns: ['Title', 'Author', 'ISBN', 'Copies'], value: { op: 'sum', col: 3 }, query: () => sql`select title, coalesce(author, ''), coalesce(isbn, ''), coalesce(copies, 1) from library_books order by 1` },
  eresources: { label: 'E-resources subscribed', basis: 'E-resources registered and active', columns: ['Resource', 'Kind', 'Publisher', 'Licence until'], query: () => sql`select title, kind, coalesce(publisher, ''), licence_until::text from library_eresources where coalesce(status, 'active') = 'active' order by 1` },
  fees_lakhs: { label: 'Fee receipts (INR lakhs)', basis: 'Fees paid against invoices raised in the year', columns: ['Invoice', 'Title', 'Due on', 'Paid (INR lakhs)'], value: { op: 'sum', col: 3 }, query: (y) => sql`select coalesce(invoice_no, ''), title, due_on::text, round(paid_paise / 1e7, 4)::float8 from fee_invoices where status <> 'cancelled' and created_at::date between ${y.from}::date and ${y.to}::date order by 3` },

  // ---- governance, IQAC and feedback -----------------------------------------------------------------------------------
  iqac_meetings: { label: 'IQAC meetings held', basis: 'IQAC meetings minuted in the year', columns: ['Meeting', 'Date'], query: (y) => sql`select title, meeting_on::text from iqac_meetings where meeting_on between ${y.from}::date and ${y.to}::date order by 2` },
  feedback_respondents: { label: 'Feedback responses received', basis: 'Survey responses submitted in the year', columns: ['Survey', 'Audience', 'Submitted on'], query: (y) => sql`select s.title, s.audience::text, r.submitted_at::date::text from survey_responses r join surveys s on s.id = r.survey_id where r.submitted_at::date between ${y.from}::date and ${y.to}::date order by 3` },
  feedback_rating: { label: 'Average stakeholder rating (out of 5)', basis: 'Mean of rating answers to surveys answered in the year', columns: ['Survey', 'Responses', 'Average rating'], value: { op: 'avg', col: 2 }, query: (y) => sql`select s.title, count(distinct r.id)::int, round(avg(a.rating)::numeric, 2)::float8 from survey_answers a join survey_responses r on r.id = a.response_id join surveys s on s.id = r.survey_id where a.rating is not null and r.submitted_at::date between ${y.from}::date and ${y.to}::date group by s.title order by 1` },
  school_sections: { label: 'Sections', basis: 'Classes and sections of the academic year', columns: ['Class', 'Section', 'Students'], query: (y) => sql`select pr.name, s.display_name, (select count(*)::int from students st where st.section_id = s.id and st.status in ('enrolled', 'active')) from sections s join programs pr on pr.id = s.program_id join academic_years ay on ay.id = s.academic_year_id where ay.starts_on <= ${y.to}::date and ay.ends_on >= ${y.from}::date order by 1, 2` },
  statutory_committees: { label: 'Statutory committees active', basis: 'Statutory committees that met in the year', columns: ['Committee', 'Meetings'], query: (y) => sql`select c.name, count(m.id)::int from committees c join committee_meetings m on m.committee_id = c.id where c.statutory and m.meeting_on between ${y.from}::date and ${y.to}::date group by c.name order by 1` },
};

const num = (v: unknown): number | null => (v === null || v === undefined || v === '' || Number.isNaN(Number(v)) ? null : Number(v));
const round = (v: number | null, d = 4) => (v === null ? null : Math.round(v * 10 ** d) / 10 ** d);

/** The figure of a source from its rows. */
export function sourceValue(def: Pick<SourceDef, 'value'>, rows: Cell[][]): number | null {
  const op = def.value ?? { op: 'count' };
  if (op.op === 'count') return rows.length;
  if (op.op === 'distinct') return new Set(rows.map((r) => String(r[op.col] ?? ''))).size;
  const xs = rows.map((r) => num(r[op.col])).filter((x): x is number => x !== null);
  if (op.op === 'sum') return round(xs.reduce((a, b) => a + b, 0));
  if (!xs.length) return null;
  if (op.op === 'avg') return round(xs.reduce((a, b) => a + b, 0) / xs.length);
  const s = [...xs].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return round(s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2);
}

/**
 * Runs sources for the years asked, once per (source, year). A source whose tables a tenant has not used simply returns
 * zero rows; a query error (a module not migrated in this deployment) is reported as no data rather than failing the page.
 */
export class SourceCache {
  private readonly done = new Map<string, Promise<SourceResult>>();
  /** Queries run one after another: they share the request's transaction, which takes one query at a time. */
  private chain: Promise<unknown> = Promise.resolve();
  constructor(private readonly tx: Tx) {}

  get(key: string, y: AcademicYear): Promise<SourceResult> {
    const id = `${key}@${y.label}`;
    let p = this.done.get(id);
    if (!p) {
      p = this.chain.then(() => this.run(key, y));
      this.chain = p.catch(() => undefined);
      this.done.set(id, p);
    }
    return p;
  }

  private async run(key: string, y: AcademicYear): Promise<SourceResult> {
    const def = SOURCES[key];
    if (!def) return { value: null, columns: [], rows: [] };
    // A savepoint keeps a failing optional query from aborting the request's transaction.
    const rows = await this.tx
      .transaction(async (sp) => ((await sp.execute(def.query(y))).rows as Record<string, unknown>[]).map((r) => Object.values(r).map((v) => (v === null || v === undefined ? null : typeof v === 'number' ? v : v instanceof Date ? v.toISOString().slice(0, 10) : String(v))) as Cell[]))
      .catch(() => null);
    if (rows === null) return { value: null, columns: def.columns, rows: [] };
    return { value: sourceValue(def, rows), columns: def.columns, rows };
  }
}
